local lpeg = require "lpeg"
local util = require "lib.util"
local split_trim = util.split_trim
local trim = util.trim
local toboolean = util.toboolean

return function(automata)
    -- label "input pop/push" as an LPeg pattern, shared by the tuple
    -- grammar (bounded by the next field boundary) and by parse_label
    -- for programmatic add_transition (bounded by end of string); it
    -- reproduces the former string.find pattern
    -- "^%s*([^%s]*)%s+(.*)%s*/%s*(.*)%s*$" including its quirks: input
    -- may be empty when the label starts with whitespace, and pop is
    -- greedy up to the *last* "/" before the boundary
    local sp = lpeg.S" \t\n\r\f\v"
    local function pda_label_pattern(fend)
        local sep_input = (sp^0 * lpeg.C((1 - sp)^0) * #(sp^1) * sp^1)
                       + (sp^1 * lpeg.Cc(""))
        local last_slash = lpeg.P"/" * (1 - (lpeg.P"/" + fend))^0 * fend
        local pop = lpeg.C((1 - (last_slash + fend + lpeg.P"\n"))^0)
        local push = lpeg.C((1 - (fend + lpeg.P"\n"))^0)
        return sep_input * pop * sp^0 * lpeg.P"/" * sp^0 * push * sp^0
    end
    automata.pda_label_string = pda_label_pattern(lpeg.P(-1))
                              * lpeg.P(-1)
    automata.pda_label_field = pda_label_pattern(automata.tuple_field_end)

    local stack_alphabet = {
        name="stack_alphabet",
        parse_lpeg=automata.tuple_braced,
        parse_action = function(automaton, symbols)
            symbols = split_trim(symbols)
            for _,s in ipairs(symbols) do
                if s ~= "" then
                    automaton:add_stack_symbol(s)
                end
            end
        end,
        get_string = function(automaton)
            return tostring(automaton:get_stack_symbols())
        end
    }

    local pda_transitions = {
        name="transitions",
        parse_lpeg=automata.tuple_transitions_with(
            lpeg.Ct(automata.pda_label_field)),
        parse_action = function(automaton, transitions)
            for _, triple in ipairs(transitions) do
                automaton:add_transition(trim(triple[1]),
                                         triple[2],
                                         trim(triple[3]))
            end
        end,
        get_string =
            automata.standard_tuple_entries.transitions.get_string
    }

    local pda_tuple_entries = {
        automata.standard_tuple_entries.states,
        automata.standard_tuple_entries.symbols,
        stack_alphabet,
        pda_transitions,
        automata.standard_tuple_entries.initial_state,
        automata.standard_tuple_entries.accepting_states
    }

    local label_metatable = {
        __tostring = function(self)
            local input = self.input
            if input == "" then
                input = "λ"
            end
            local pop = self.pop
            if pop == "" then
                pop = "λ"
            end
            local push = self.push
            if push == "" then
                push = "λ"
            end
            return string.format("%s %s/%s", input, pop, push)
        end
    }

    function automata.make_pda(extended)
        local function parse_label(self, label)
            local input, pop, push
            if type(label) == "table" then
                -- already split by the tuple grammar's label pattern
                input, pop, push = label[1], label[2], label[3]
            else
                label = trim(label)
                input, pop, push =
                    lpeg.match(automata.pda_label_string, label)
            end
            assert(input, "input incorrect")
            assert(pop, "pop incorrect")
            assert(push, "push incorrect")
            input = trim(input)
            input = input:gsub("λ+", "")
            assert(automata.tokenise_word(input):len() <= 1, "Incorrect input character in PDA")
            pop = trim(pop)
            pop = pop:gsub("λ+", "")
            assert(automata.tokenise_word(pop):len() <= 1, "Incorrect pop character in PDA")
            push = trim(push)
            push = push:gsub("λ+", "")
            if extended and push ~= "" then
                push = automata.tokenise_word(push)
            end
            assert(extended or automata.tokenise_word(push):len() <= 1, "Incorrect pop character in PDA")
            local result = {input=input, pop=pop, push=push}
            setmetatable(result, label_metatable)
            return result
        end

        local function after_add_transition(self, transition)
            local from = transition.from
            local label = transition.label
            local to = transition.target
            if label.input ~= "" and not self:has_symbol(label.input) then
                self:add_symbol(label.input)
            end
            if label.pop ~= "" and not self:has_stack_symbol(label.pop) then
                self:add_stack_symbol(label.pop)
            end
            if label.push ~= ""
                    and not automata.is_empty_token_sequence(label.push)
                    and not self:has_stack_symbol(label.push) then
                if automata.is_token_sequence(label.push) then
                    for i=1,label.push:len() do
                        self:add_stack_symbol(label.push:get_char(i))
                    end
                else
                    self:add_stack_symbol(label.push)
                end
            end
            if not self.transitions_to[from] then
                self.transitions_to[from] = {}
            end
            if not self.transitions_to[from][label.input] then
                self.transitions_to[from][label.input] = {}
            end
            if not self.transitions_to[from][label.input][label.pop] then
                self.transitions_to[from][label.input][label.pop] = {}
            end
            self.transitions_to[from][label.input][label.pop][transition] = true
        end

        local pda = automata.make_automaton_basic({
            type="pda",
            after_add_transition=after_add_transition,
            tuple = pda_tuple_entries,
            parse_label = parse_label
        })

        pda.transitions_to = {}
        pda.stack_symbols = util.make_ordered_set()

        function pda:add_stack_symbol(symbol)
            assert(symbol ~= "")
            self.stack_symbols[symbol] = true
        end

        function pda:get_stack_symbols()
            assert(self)
            return self.stack_symbols
        end

        function pda:has_stack_symbol(symbol)
            return toboolean(self.stack_symbols[symbol])
        end

        function pda:get_to_transitions(from, input, stack_top)
            assert(self)
            assert(type(from) == "string", type(from))
            assert(type(input) == "string", type(input))
            if not from then
                return nil
            end
            -- pure read: misses must not grow transitions_to with
            -- empty nested tables (this is called per BFS step)
            local by_input = self.transitions_to[from]
            local by_top = by_input and by_input[input]
            return (by_top and by_top[stack_top]) or {}
        end

        return pda
    end

    function automata.is_finished_pda(what)
        local result, message = automata.is_finished_automaton(what)
        if not result then
            return result, message
        end
        if what:get_type() ~= "pda" then
            return false, "Automaton is not a PDA"
        end
        return true
    end

    function automata.parse_pda(from)
        return automata.parse_automaton(automata.make_pda, from, pda_tuple_entries)
    end

    function automata.parse_pda_extended(from)
        return automata.parse_automaton(function() return automata.make_pda(true) end, from, pda_tuple_entries)
    end

end
